(async function(){'use strict';const status=document.getElementById('status');if(location.protocol==='file:'){status.textContent='静态入口已停用，请使用项目服务。';const a=document.createElement('a');a.href='http://127.0.0.1:8766/';a.textContent='进入身体中心工作台';a.style.cssText='position:absolute;top:45%;left:25%;padding:20px;background:#244b64;color:white;z-index:99';document.getElementById('stage').appendChild(a);return;}async function script(src){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(Error('加载失败 '+src));document.body.appendChild(s);});}try{status.textContent='加载数据清单与本地模块…';for(const name of ['data','timeline','transforms','service','inspection','navigation','layers'])await script('/modules/'+name+'.js');window.VIEWER_MANIFEST=await Workbench.service.api('/api/manifest');status.textContent='加载快照 '+window.VIEWER_MANIFEST.run_id+'…';const snapshot={meta:window.VIEWER_MANIFEST.meta||{}};for(const item of window.VIEWER_MANIFEST.datasets){if(!['body','neural','electrodes','calcium','bench'].includes(item.dataset_id))continue;status.textContent='加载 '+item.dataset_id+' · '+window.VIEWER_MANIFEST.run_id;const section=await Workbench.service.api(item.data_url);snapshot[item.dataset_id]=section;}const live=await Workbench.service.api('/api/status');snapshot.bench={...live.bench,chain:snapshot.bench?.chain||[]};window.VIEWER_DATA=Workbench.data.validate(snapshot);window.VIEWER_METADATA=Workbench.data.metadata(window.VIEWER_DATA,window.VIEWER_MANIFEST);await script('/app.js');}catch(e){status.textContent='工作台加载失败：'+e.message;window.viewerErrors.push(e.message);}})();
